package org.brightstats.model;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.stats.*;
public final class AdjustedCopulaDiagramChecks {
    private static int checks;
    private static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid adjusted diagram accepted");}catch(IllegalArgumentException expected){checks++;}}
    private static Document anchor(Document document,String id,String edge){JsonObject properties=new JsonObject();properties.addProperty("edge",edge);return document.with(new Node(id,ElementType.DONGLE,"",0,0,properties));}
    private static Document marker(Document document,String id,String edge){document=anchor(document,id+"_anchor",edge);return document.with(new Node(id,ElementType.GAUSSIAN_COPULA,"Adjusted control",100,100,new JsonObject())).with(new Link(id+"_link",ElementType.CONNECTION_BETWEEN_GAUSSIAN_COPULA_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION,id,id+"_anchor",new JsonObject()));}
    private static Document enable(Document document){var root=document.node(document.root());var properties=root.properties();properties.addProperty("copulaEstimator","ADJUSTED_2025");return document.with(new Node(root.id(),root.type(),root.label(),root.x(),root.y(),properties));}
    public static void main(String[] args)throws Exception{Path output=Path.of(args[0]);Files.createDirectories(output);var json=new GsonBuilder().serializeSpecialFloatingPointValues().serializeNulls().setPrettyPrinting().create();Path fixtures=Path.of(args[1]);var components=JsonParser.parseString(Files.readString(fixtures.resolve("components.json"))).getAsJsonArray();var fixture=components.get(0).getAsJsonObject();double[][] data=new Gson().fromJson(fixture.get("observations"),double[][].class);var model=org.brightstats.data.ComponentCopulaInput.model(fixture.get("model"));List<String> columns=List.of("x1","x2","w1","w2","z","m1","m2","y1","y2");JsonArray records=new JsonArray();
        for(var family:List.of(Family.PLS,Family.GSCA)){Document document=family==Family.PLS?DiagramTemplates.pls(columns,model.blocks(),model.paths()):DiagramTemplates.gsca(org.brightstats.data.ComponentCopulaInput.model(components.get(1).getAsJsonObject().get("model")).gscaModel());String prefix=family==Family.PLS?"c":"g";var xm=document.links().stream().filter(link->link.type().structural()&&link.source().equals(prefix+0)&&link.target().equals(prefix+3)).findFirst().orElseThrow();var my=document.links().stream().filter(link->link.type().structural()&&link.source().equals(prefix+3)&&link.target().equals(prefix+4)).findFirst().orElseThrow();document=marker(marker(document,"gc_x",xm.id()),"gc_m",my.id());document=anchor(document,"quadratic_anchor",xm.id()).with(new Node("quadratic",ElementType.QUADRATIC_EFFECT,"X squared",100,100,new JsonObject())).with(new Link("square",ElementType.CONNECTION_BETWEEN_QUADRATIC_EFFECT_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION,"quadratic","quadratic_anchor",new JsonObject()));document=anchor(document,"moderation_anchor",my.id()).with(new Link("interaction",family==Family.PLS?ElementType.CONNECTION_FOR_PLS_MODERATION:ElementType.CONNECTION_FOR_GSCA_MODERATION,prefix+0,"moderation_anchor",new JsonObject()));add(records,enable(document),columns,data,json);}
        var observed=JsonParser.parseString(Files.readString(fixtures.resolve("cases.json"))).getAsJsonArray();var systemCase=observed.get(3).getAsJsonObject();double[][] raw=new Gson().fromJson(systemCase.get("observations"),double[][].class);List<String> names=List.of("P","Q","W","Z","M","Y");var paths=org.brightstats.data.PlsModelInput.edges(systemCase.getAsJsonObject("model").get("paths"));List<PathProcess.Path> processPaths=paths.stream().map(edge->new PathProcess.Path(edge.source(),edge.target())).toList();Document process=DiagramTemplates.process(names,new PathProcess.Model(0,5,processPaths,new int[]{2,3}));var xm=process.links().stream().filter(link->link.type().structural()&&link.source().equals("p0")&&link.target().equals("p4")).findFirst().orElseThrow();var my=process.links().stream().filter(link->link.type().structural()&&link.source().equals("p4")&&link.target().equals("p5")).findFirst().orElseThrow();process=marker(marker(process,"gc_x",xm.id()),"gc_m",my.id());process=anchor(process,"quadratic_anchor",xm.id()).with(new Node("quadratic",ElementType.PROCESS_MODEL_QUADRATIC_EFFECT,"P squared",100,100,new JsonObject())).with(new Link("square",ElementType.CONNECTION_BETWEEN_PROCESS_QUADRATIC_EFFECT_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION,"quadratic","quadratic_anchor",new JsonObject()));process=enable(process);add(records,process,names,raw,json);
        var simple=observed.get(0).getAsJsonObject();double[][] regression=new Gson().fromJson(simple.get("observations"),double[][].class);var linear=enable(marker(DiagramTemplates.regression(List.of("X","W","Y"),2,new int[]{0,1},true),"gc_x","path0"));add(records,linear,List.of("X","W","Y"),regression,json);var missing=process.with(new Node("orphan_gc",ElementType.GAUSSIAN_COPULA,"Orphan",0,0,new JsonObject()));reject(()->DiagramAdjustedCopula.compile(missing,names,raw));var root=process.node(process.root());var invalid=root.properties();JsonObject processOptions=new JsonObject();processOptions.addProperty("metric","STANDARDIZED");invalid.add("processOptions",processOptions);var wrongMetric=process.with(new Node(root.id(),root.type(),root.label(),root.x(),root.y(),invalid));reject(()->DiagramAdjustedCopula.compile(wrongMetric,names,raw));Files.writeString(output.resolve("diagrams.json"),json.toJson(records));System.out.println("Adjusted diagram checks: "+checks);}
    private static void add(JsonArray records,Document document,List<String> names,double[][] data,Gson json){String before=document.json().toString();var compiled=DiagramAdjustedCopula.compile(document,names,data);require(before.equals(document.json().toString()),"Compiler changed original diagram");require(compiled.system().corrections().size()==(document.family()==Family.REGRESSION?1:2),"All marked equations retained");require(compiled.system().extensions().size()==(document.family()==Family.REGRESSION?0:document.family()==Family.PROCESS?1:2),"Polynomial attachments retained");AdjustedCopula.Fit point;if(compiled.component()==null)point=AdjustedCopula.fit(compiled.observations(),compiled.system());else point=ComponentAdjustedCopula.fit(compiled.observations(),compiled.component(),new ComponentAdjustedCopula.Specification(compiled.system(),compiled.binaryBindings())).correction();require(point.equations().size()==(document.family()==Family.REGRESSION?1:2),"Intended equations fitted");JsonObject record=new JsonObject();record.add("document",document.json());record.add("columnNames",json.toJsonTree(names));record.add("observations",json.toJsonTree(data));record.add("compiled",json.toJsonTree(compiled));record.add("fit",json.toJsonTree(point));records.add(record);}
}
